package com.sathavahana.kalamkari.domain;
import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="order_items") public class OrderItem { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="order_id") private Order order; @ManyToOne(fetch=FetchType.LAZY) private Product product; @Column(name="product_name") private String productName; private int quantity; @Column(name="unit_price") private BigDecimal unitPrice; public OrderItem(){} public OrderItem(Order o,Product p,int q){order=o;product=p;productName=p.getName();quantity=q;unitPrice=p.getPrice();} public Product getProduct(){return product;} public int getQuantity(){return quantity;} public BigDecimal getUnitPrice(){return unitPrice;}}
